<template><q-dialog v-model="visible"><q-card class="detail-card"><q-card-section class="row justify-between items-center bg-green-8 text-white"><div><div class="text-h6 text-weight-bold">Detalle del lote</div><div class="text-caption">{{ lote?.codigoLote }}</div></div><q-btn flat round icon="close" v-close-popup/></q-card-section><q-card-section v-if="lote"><div class="text-h6 text-green-9 q-mb-xs">{{ lote.producto }}</div><div class="row q-col-gutter-md q-mt-md"><div v-for="d in detalles" :key="d.label" class="col-12 col-sm-6 col-md-4"><div class="label">{{ d.label }}</div><div class="value">{{ d.value || '—' }}</div></div></div><q-separator class="q-my-md"/><div class="text-subtitle1 text-weight-bold text-green-9 q-mb-sm">Existencia del lote</div><div class="row q-col-gutter-md"><div class="col-12 col-sm-4"><div class="label">Cantidad total</div><div class="value">{{ lote.cantidad ?? 0 }}</div></div><div class="col-12 col-sm-4"><div class="label">Almacén</div><div class="value">{{ lote.almacen || '—' }}</div></div><div class="col-12 col-sm-4"><div class="label">Ubicación</div><div class="value">{{ lote.ubicacion || '—' }}</div></div></div></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cerrar" color="green-8" v-close-popup/><q-btn unelevated no-caps label="Ver Kardex" icon="receipt_long" color="green-8" @click="emit('kardex',lote)"/></q-card-actions></q-card></q-dialog></template>
<script setup>import{computed}from'vue';const props=defineProps({modelValue:Boolean,lote:Object});const emit=defineEmits(['update:modelValue','kardex']);const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});const detalles=computed(()=>props.lote?[{label:'Producto',value:props.lote.producto},{label:'Código de lote',value:props.lote.codigoLote},{label:'Fecha de ingreso',value:props.lote.fechaIngreso},{label:'Fecha de fabricación',value:props.lote.fechaFabricacion},{label:'Fecha de vencimiento',value:props.lote.fechaVencimiento},{label:'Estado',value:props.lote.estado},{label:'Observación',value:props.lote.observacion}]:[])</script><style scoped>.detail-card{width:760px;max-width:95vw;border-radius:18px}.label{font-size:11px;color:#7c8b78;text-transform:uppercase;font-weight:800}.value{font-weight:700;color:#29472d;margin-top:3px}</style>
